[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [ValidateSet("MoveDraft","EditNote","Restore")]
    [string]$Action,

    [Parameter(Mandatory = $true)]
    [ValidateSet("Preview","Apply")]
    [string]$Mode,

    [string]$SourceDraft,
    [string]$TargetRelativePath,
    [string]$NewContent,
    [string]$NewContentFile,
    [string]$RecoveryFile,
    [string]$ApprovalToken,

    [switch]$Json
)

$ErrorActionPreference = "Stop"

$Container = "orion-vault-broker"
$Payload = ""

function Invoke-BrokerRequest {
    param([Parameter(Mandatory = $true)][hashtable]$Request)

    $requestJson = $Request | ConvertTo-Json -Compress -Depth 8
    $loader = "import base64; exec(base64.b64decode('$Payload'))"

    $raw = $requestJson | & docker exec -i `
        -u 10000:10000 `
        $Container `
        /opt/iai/venv/bin/python -c $loader 2>&1

    $code = $LASTEXITCODE
    $text = (($raw | ForEach-Object { [string]$_ }) -join "`n").Trim()

    if ([string]::IsNullOrWhiteSpace($text)) {
        throw "Vault broker returned no output."
    }

    try {
        $obj = $text | ConvertFrom-Json -ErrorAction Stop
    }
    catch {
        throw ("Vault broker returned non-JSON output (exit {0}): {1}" -f $code, $text)
    }

    return [pscustomobject]@{
        ExitCode = $code
        Object = $obj
    }
}

$running = @(& docker ps --format "{{.Names}}")
if ($LASTEXITCODE -ne 0) {
    throw "Could not list running Docker containers."
}
if ($running -notcontains $Container) {
    throw "Controlled vault broker '$Container' is not running."
}

$request = @{
    action = $Action.ToLowerInvariant() -replace "draft","_draft" -replace "note","_note"
    mode = $Mode.ToLowerInvariant()
}

if ($Action -eq "MoveDraft") {
    if ([string]::IsNullOrWhiteSpace($SourceDraft) -or [string]::IsNullOrWhiteSpace($TargetRelativePath)) {
        throw "MoveDraft requires -SourceDraft and -TargetRelativePath."
    }
    $request.action = "move_draft"
    $request.source_draft = $SourceDraft
    $request.target_relative_path = $TargetRelativePath
}
elseif ($Action -eq "EditNote") {
    if ([string]::IsNullOrWhiteSpace($TargetRelativePath)) {
        throw "EditNote requires -TargetRelativePath."
    }
    if (-not [string]::IsNullOrWhiteSpace($NewContentFile)) {
        if (-not (Test-Path -LiteralPath $NewContentFile -PathType Leaf)) {
            throw "New content file not found: $NewContentFile"
        }
        $NewContent = Get-Content -LiteralPath $NewContentFile -Raw
    }
    if ($null -eq $NewContent) {
        throw "EditNote requires -NewContent or -NewContentFile."
    }
    $request.action = "edit_note"
    $request.target_relative_path = $TargetRelativePath
    $request.new_content = $NewContent
}
else {
    if ([string]::IsNullOrWhiteSpace($TargetRelativePath) -or [string]::IsNullOrWhiteSpace($RecoveryFile)) {
        throw "Restore requires -TargetRelativePath and -RecoveryFile."
    }
    $request.action = "restore"
    $request.target_relative_path = $TargetRelativePath
    $request.recovery_file = $RecoveryFile
}

if ($Mode -eq "Apply") {
    if ([string]::IsNullOrWhiteSpace($ApprovalToken)) {
        throw "Apply requires the exact -ApprovalToken returned by Preview."
    }
    $request.approval_token = $ApprovalToken
}

$result = Invoke-BrokerRequest -Request $request

# A policy denial is an expected broker outcome, not a broker failure.
# Handle it before generic non-zero-exit handling so callers can verify
# denied-action no-op behavior without receiving a PowerShell exception.
if ($result.Object.status -eq "denied") {
    if ($Json) {
        $result.Object | ConvertTo-Json -Depth 8
        exit 20
    }
    Write-Host "ORION_VAULT_BROKER=DENIED"
    Write-Host ("REASON={0}" -f $result.Object.error)
    exit 20
}

if ($result.ExitCode -ne 0 -or $result.Object.status -ne "ok") {
    throw ("Vault broker failed: {0}" -f ($result.Object | ConvertTo-Json -Compress -Depth 8))
}

if ($Json) {
    $result.Object | ConvertTo-Json -Depth 8
    exit 0
}

if ($Mode -eq "Preview") {
    Write-Host "ORION_VAULT_BROKER_PREVIEW=PASS"
    Write-Host ("ACTION={0}" -f $result.Object.action)
    if ($result.Object.source_draft) {
        Write-Host ("SOURCE_DRAFT={0}" -f $result.Object.source_draft)
    }
    if ($result.Object.target_relative_path) {
        Write-Host ("TARGET_RELATIVE_PATH={0}" -f $result.Object.target_relative_path)
    }
    if ($result.Object.recovery_file) {
        Write-Host ("RECOVERY_FILE={0}" -f $result.Object.recovery_file)
    }
    Write-Host ("APPROVAL_TOKEN={0}" -f $result.Object.approval_token)
    Write-Host ""
    Write-Host "--- DIFF BEGIN ---"
    Write-Output ([string]$result.Object.diff)
    Write-Host "--- DIFF END ---"
}
else {
    Write-Host "ORION_VAULT_BROKER_APPLY=PASS"
    Write-Host ("ACTION={0}" -f $result.Object.action)
    if ($result.Object.target_relative_path) {
        Write-Host ("TARGET_RELATIVE_PATH={0}" -f $result.Object.target_relative_path)
    }
    if ($result.Object.result_sha256) {
        Write-Host ("RESULT_SHA256={0}" -f $result.Object.result_sha256)
    }
    if ($result.Object.recovery_id) {
        Write-Host ("RECOVERY_ID={0}" -f $result.Object.recovery_id)
        Write-Host ("RECOVERY_FILE={0}" -f $result.Object.recovery_file)
    }
}
